head.b:skin:
/* Reset default Blogger garbage */
.navbar, #navbar, .widget-item-control, .quickedit, .status-msg-wrap { display: none !important; }

html, body {
  margin: 0;
  padding: 0;
  background-color: #040609 !important;
  color: #e2e8f0;
  font-family: 'Space Grotesk', system-ui, sans-serif;
  overflow-x: hidden;
}

.font-cyber { font-family: 'Orbitron', system-ui, sans-serif; }
.font-mono { font-family: 'JetBrains Mono', monospace; }
.font-tech { font-family: 'Rajdhani', sans-serif; }

/* Frosted Cyber Glassmorphism */
.glass-panel {
  background: rgba(8, 14, 26, 0.75);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 240, 255, 0.18);
}
.glass-panel-crimson {
  background: rgba(20, 6, 12, 0.75);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 0, 85, 0.3);
}
.glass-card-hover {
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.glass-card-hover:hover {
  transform: translateY(-4px);
  border-color: rgba(0, 240, 255, 0.5);
  box-shadow: 0 10px 30px -10px rgba(0, 240, 255, 0.3), 0 0 1px 1px rgba(0, 240, 255, 0.3);
}
.cyber-grid {
  background-size: 40px 40px;
  background-image: 
    linear-gradient(to right, rgba(0, 240, 255, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 240, 255, 0.04) 1px, transparent 1px);
}

/* Scanlines & Animations */
.animate-scan {
  animation: scanAnim 2.5s ease-in-out infinite;
}
@keyframes scanAnim {
  0% { top: 0%; opacity: 0.8; }
  50% { top: 96%; opacity: 1; }
  100% { top: 0%; opacity: 0.8; }
}
@keyframes pulseGlowAnim {
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.03); }
}
.animate-pulse-glow {
  animation: pulseGlowAnim 4s ease-in-out infinite;
}

/* Custom Cyber Scrollbars */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: #040609; }
::-webkit-scrollbar-thumb { background: #152238; border-radius: 4px; border: 1px solid rgba(0, 240, 255, 0.2); }
::-webkit-scrollbar-thumb:hover { background: rgba(0, 240, 255, 0.5); }

/* Hidden tabs */
.tab-content { display: none; }
.tab-content.active { display: block; animation: fadeIn 0.3s ease-in-out; }
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

body.script:
//
// Live Clock
function updateClock() {
  const now = new Date();
  const el = document.getElementById('live-clock');
  if (el) el.innerText = now.toLocaleTimeString('en-US', { hour12: false }) + ' UTC';
}
setInterval(updateClock, 1000);
updateClock();

// Tab Switching
function switchTab(tabId) {
  document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
  const target = document.getElementById('tab-' + tabId);
  if (target) target.classList.add('active');

  document.querySelectorAll('.nav-btn').forEach(btn => {
    if (btn.getAttribute('data-tab') === tabId) {
      btn.className = 'nav-btn active flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-mono transition-all bg-cyan-500/25 text-cyan-300 border border-cyan-500/50 shadow-[0_0_12px_rgba(0,240,255,0.3)] font-bold';
    } else {
      btn.className = 'nav-btn flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-mono transition-all text-slate-300 hover:text-cyan-300 hover:bg-cyan-500/10';
    }
  });
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Modals
function openModal(id) {
  const el = document.getElementById(id);
  if (el) el.classList.remove('hidden');
}
function closeModal(id) {
  const el = document.getElementById(id);
  if (el) el.classList.add('hidden');
}

// Mobile Menu
function toggleMobileMenu() {
  const el = document.getElementById('mobile-drawer');
  if (el) el.classList.toggle('hidden');
}

// Confetti
function triggerConfetti() {
  if (typeof confetti === 'function') {
    confetti({ particleCount: 80, spread: 70, origin: { y: 0.6 } });
  }
}

// GRUB Simulator Logic
let selectedGrubIndex = 0;
const grubLogDescriptions = [
  '[OK] Booting Debian 12 (Kernel 6.12 Liquorix)... Loading 4K Frosted Glass UI in 15s.',
  '[OK] Loading Recovery Root... Immutable Chattr status: VERIFIED SECURE.',
  '[OK] Launching Waydroid Subsystem... Initializing Android 11 Mesa GPU buffer.',
  '[OK] Mounting WineHQ 9.0 prefix... Windows compatibility layer online.'
];

function selectGrubEntry(index) {
  selectedGrubIndex = index;
  const entries = document.querySelectorAll('.grub-entry');
  entries.forEach((el, idx) => {
    if (idx === index) {
      el.className = 'grub-entry active p-3 rounded-lg bg-cyan-500/20 border border-cyan-500 text-cyan-300 font-bold cursor-pointer';
    } else {
      el.className = 'grub-entry p-3 rounded-lg bg-slate-900/60 border border-slate-800 text-slate-400 cursor-pointer hover:border-slate-700';
    }
  });
}

function bootSelectedEntry() {
  const out = document.getElementById('boot-log-output');
  if (out) {
    out.innerHTML = '<span class="text-cyan-400 font-bold">>>> EXECUTE: </span>' + grubLogDescriptions[selectedGrubIndex];
  }
}

// Terminal Emulator
const terminalInput = document.getElementById('terminal-input');
const terminalLog = document.getElementById('terminal-log');
if (terminalInput && terminalLog) {
  terminalInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      const cmd = terminalInput.value.trim().toLowerCase();
      terminalInput.value = '';
      const line = document.createElement('div');
      line.className = 'text-cyan-300';
      line.innerText = '$ ' + cmd;
      terminalLog.appendChild(line);

      const resp = document.createElement('div');
      if (cmd === 'clear') {
        terminalLog.innerHTML = '<div>[INFO] Terminal cleared.</div>';
        return;
      } else if (cmd === 'uname -a') {
        resp.className = 'text-slate-300';
        resp.innerText = 'Linux ritesh-pc 6.12.8-liquorix-amd64 #1 ZEN SMP PREEMPT x86_64 GNU/Linux';
      } else if (cmd === 'neofetch' || cmd === 'fetch') {
        resp.className = 'text-cyan-400';
        resp.innerHTML = 'OS: RITESH PC OS v2.0<br/>Host: Cybernetic Hybrid Suite<br/>Kernel: 6.12.8-liquorix<br/>DE: 4K Frosted Glass<br/>Memory: 450MB / 16384MB';
      } else {
        resp.className = 'text-amber-400';
        resp.innerText = 'Command recognized: ' + cmd + ' [Available commands: neofetch, uname -a, clear]';
      }
      terminalLog.appendChild(resp);
      terminalLog.scrollTop = terminalLog.scrollHeight;
    }
  });
}

// Floating Cyber Particles Canvas
const canvas = document.getElementById('bg-canvas');
if (canvas) {
  const ctx = canvas.getContext('2d');
  let particles = [];
  function resize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }
  window.addEventListener('resize', resize);
  resize();

  for (let i = 0; i < 35; i++) {
    particles.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      vx: (Math.random() - 0.5) * 0.6,
      vy: (Math.random() - 0.5) * 0.6,
      radius: Math.random() * 2 + 1
    });
  }

  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'rgba(0, 240, 255, 0.4)';
    ctx.strokeStyle = 'rgba(0, 240, 255, 0.08)';

    for (let i = 0; i < particles.length; i++) {
      let p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      if (p.x < 0) p.x = canvas.width;
      if (p.x > canvas.width) p.x = 0;
      if (p.y < 0) p.y = canvas.height;
      if (p.y > canvas.height) p.y = 0;

      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fill();

      for (let j = i + 1; j < particles.length; j++) {
        let p2 = particles[j];
        let dist = Math.hypot(p.x - p2.x, p.y - p2.y);
        if (dist < 120) {
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
      }
    }
    requestAnimationFrame(animate);
  }
  animate();
}
//
